package blockbranch.realistic;
import java.nio.file.*;import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.world.level.block.Blocks;
/** Destructive native pressure-plate/TNT witness, only in an isolated copied fixture. */
public final class ReimaginedTrap {
 private static int phase,ticks,peak;private static BlockPos plate;private static net.minecraft.world.level.levelgen.structure.BoundingBox box;private static final List<net.minecraft.world.level.ChunkPos> forced=new ArrayList<>();
 public static void register(){net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents.END_SERVER_TICK.register(server->{if(phase==3)return;try{var l=server.overworld();if(phase==0){var holder=l.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.STRUCTURE).getOrThrow(ReimaginedStructures.key(2));var start=l.structureManager().getStartForStructure(holder.value(),l.getChunk(-701960>>4,270984>>4));box=start.getBoundingBox();for(int z=box.minZ()>>4;z<=box.maxZ()>>4;z++)for(int x=box.minX()>>4;x<=box.maxX()>>4;x++){l.setChunkForced(x,z,true);forced.add(new net.minecraft.world.level.ChunkPos(x,z));}phase=1;return;}
 if(phase==1){if(forced.stream().anyMatch(c->!l.areEntitiesLoaded(c.pack())))return;int tnt=0;for(var p:BlockPos.betweenClosed(box.minX(),box.minY(),box.minZ(),box.maxX(),box.maxY(),box.maxZ())){if(l.getBlockState(p).is(Blocks.STONE_PRESSURE_PLATE))plate=p.immutable();if(l.getBlockState(p).is(Blocks.TNT))tnt++;}if(plate==null||tnt!=9)throw new AssertionError("Original armed native trap before interaction");server.getCommands().performPrefixedCommand(server.createCommandSourceStack(),"summon minecraft:pig "+(plate.getX()+.5)+" "+(plate.getY()+.2)+" "+(plate.getZ()+.5)+" {NoAI:1b}");phase=2;return;}
 peak=Math.max(peak,l.getEntitiesOfClass(net.minecraft.world.entity.item.PrimedTnt.class,new net.minecraft.world.phys.AABB(plate).inflate(20)).size());if(++ticks<180)return;int remaining=0;for(var p:BlockPos.betweenClosed(box.minX(),box.minY(),box.minZ(),box.maxX(),box.maxY(),box.maxZ()))if(l.getBlockState(p).is(Blocks.TNT))remaining++;if(peak==0||remaining>=9)throw new AssertionError("Native pressure-plate activation/explosion peak="+peak+" remaining="+remaining);Files.writeString(Path.of("trap.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(Map.of("plate",plate.toShortString(),"nativePrimedTntPeak",peak,"remainingTnt",remaining,"ticks",ticks,"isolatedCopiedFixture",true)));Files.writeString(Path.of("trap-result.txt"),"PASS actual native living-entity pressure plate and TNT explosion");phase=3;for(var c:forced)l.setChunkForced(c.x(),c.z(),false);server.halt(false);
 }catch(Throwable t){phase=3;blockbranch.Blockbranch.LOGGER.error("REIMAGINED_TRAP_FAIL",t);try{Files.writeString(Path.of("trap-result.txt"),"FAIL "+t);}catch(Exception ignored){}server.halt(false);}});}
}
